CNN model = NeuralNetwork.builder()
        .add(Conv2D.builder().filters(4).kernelSize(3, 3).padding(Padding.SAME).build())
        .add(MaxPooling2D.builder().poolSize(2, 2).build())
        .add(Flatten.builder().build())
        .add(Dense.builder().units(3).activation(Activation.SOFTMAX).build())
        .build();
model.predict(Tensor.ofBCHW(2, 1, 4, 4, new double[2 * 16]));

Path path = Path.of("model.jsl");
ModelSerializer.save(path, model);
CNN restored = ModelSerializer.loadCNN(path);

OptimizerConfig adam = Optimizer.ADAM.withLearningRate(0.001);
OptimizerConfig sgd = Optimizer.SGD.withLearningRate(0.05);
OptimizerConfig custom = new OptimizerConfig(Optimizer.ADAMW, 0.002, 0.85, 0.995, 1e-7);

Conv2D same = Conv2D.builder()
        .filters(4)
        .kernelSize(3, 3)
        .padding(Padding.SAME)
        .build();

Conv2D valid = Conv2D.builder()
        .filters(4)
        .kernelSize(3, 3)
        .padding(Padding.VALID)
        .build();

Tensor<BCHW> input = Tensor.zerosBCHW(1, 2, 7, 7);
int sameWidth = same.forward(input).dimension(3);
int validWidth = valid.forward(input).dimension(3);

Layer<BSF, BSF> layer = VanillaRNN.builder().hiddenSize(4).build();
List<ParameterRef> parameters = layer.parameters();
for (ParameterRef parameter : parameters) {
    double[] values = parameter.values();
    double[] gradient = parameter.gradient();
    double scale = Math.sqrt(parameter.size());
    for (int i = 0; i < values.length; i++) {
        values[i] -= 0.01 * gradient[i] / scale;
    }
}

SelfAttention attention = SelfAttention.builder()
        .dimension(4)
        .causal(true)
        .seed(7)
        .build();
Tensor<BSF> input = Tensor.zerosBSF(2, 6, 4);
Tensor<BSF> output = attention.forward(input);
Tensor<BSF> inputGradient = attention.backward(Tensor.zerosBSF(2, 6, 4));
attention.update(Optimizer.ADAM.withLearningRate(0.001));

SequencePool pool = SequencePool.of(SequencePool.Pooling.MEAN);
Tensor<BSF> sequence = Tensor.zerosBSF(4, 6, 3);
Tensor<BC> pooled = pool.forward(sequence);
Tensor<BSF> gradient = pool.backward(Tensor.zerosBC(4, 3));

VanillaRNN rnn = VanillaRNN.builder().hiddenSize(8).seed(42).build();
Tensor<BSF> input = Tensor.zerosBSF(2, 5, 3);
Tensor<BSF> output = rnn.forward(input);
Tensor<BSF> inputGradient = rnn.backward(Tensor.zerosBSF(2, 5, 8));
rnn.update(Optimizer.SGD.withLearningRate(0.05));
